-- =====================================================================================
-- Schema do BANCO DE TESTE (H2 em memória). Espelha o src/main/resources/schema.sql,
-- trocando apenas o que o H2 não aceita do PostgreSQL:
--   SERIAL/BIGSERIAL      -> GENERATED BY DEFAULT AS IDENTITY
--   copy_index :: text    -> CAST(copy_index AS VARCHAR)
--   TEXT                  -> VARCHAR(4000)
--   índices parciais (WHERE ...) não existem no H2 e foram omitidos
-- Ao alterar o schema.sql de produção, replique a mudança aqui.
-- =====================================================================================

CREATE TABLE IF NOT EXISTS org_depart(
    depart_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    depart_code VARCHAR(20) UNIQUE,
    depart_name VARCHAR(100) NOT NULL UNIQUE,
    depart_desc VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS org_local(
    local_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    local_code VARCHAR(20) UNIQUE,
    local_name VARCHAR(100) NOT NULL UNIQUE,
    local_desc VARCHAR(100) NOT NULL,
    depart_code VARCHAR,
    FOREIGN KEY (depart_code) REFERENCES org_depart(depart_code)
);

CREATE TABLE IF NOT EXISTS org_books(
    book_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    isbn VARCHAR(15) NOT NULL UNIQUE,
    title VARCHAR(100) NOT NULL,
    author VARCHAR(100) NOT NULL,
    rel_year INT,
    publisher VARCHAR(50),
    genre VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS org_copies(
    copy_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    isbn VARCHAR(25) REFERENCES org_books(isbn),
    depart_code VARCHAR REFERENCES org_depart(depart_code),
    local_code  VARCHAR REFERENCES org_local(local_code),
    copy_index INT NOT NULL,
    copy_custom_code VARCHAR(60) GENERATED ALWAYS AS (isbn || depart_code || local_code || CAST(copy_index AS VARCHAR)),
    status VARCHAR(20) DEFAULT 'AVAILABLE',
    UNIQUE (isbn, copy_index)
);

CREATE INDEX IF NOT EXISTS idx_copies_isbn ON org_copies(isbn);

CREATE TABLE IF NOT EXISTS sys_roles(
    role_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_code VARCHAR(20) UNIQUE NOT NULL,
    role_name VARCHAR(50) NOT NULL UNIQUE,
    role_desc VARCHAR(100) NOT NULL,
    is_root BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS org_users(
    user_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    custom_id VARCHAR(30) UNIQUE,
    username VARCHAR(30) NOT NULL UNIQUE,
    complete_name VARCHAR(100) NOT NULL,
    email VARCHAR(40) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role_code VARCHAR(30) REFERENCES sys_roles(role_code),
    status BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS sys_permissions(
    permission_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    permission_code VARCHAR(50) UNIQUE NOT NULL,
    resource VARCHAR(30) NOT NULL,
    action VARCHAR(30) NOT NULL,
    description VARCHAR(100)
);

CREATE TABLE IF NOT EXISTS sys_role_permissions(
    role_code VARCHAR(20) NOT NULL REFERENCES sys_roles(role_code) ON DELETE CASCADE,
    permission_code VARCHAR(50) NOT NULL REFERENCES sys_permissions(permission_code) ON DELETE CASCADE,
    PRIMARY KEY (role_code, permission_code)
);

CREATE TABLE IF NOT EXISTS auditTrail_logs(
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    time_stamp TIMESTAMP NOT NULL,
    username VARCHAR(30),
    action VARCHAR(30) NOT NULL,
    details VARCHAR(4000)
);

CREATE INDEX IF NOT EXISTS idx_audit_occurred_at ON auditTrail_logs(time_stamp DESC);
CREATE INDEX IF NOT EXISTS idx_audit_username    ON auditTrail_logs(username);

CREATE TABLE IF NOT EXISTS sys_mfa(
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL REFERENCES org_users(user_id) ON DELETE CASCADE,
    code_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    attempts INT NOT NULL DEFAULT 0,
    used_at TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_mfa_user_created ON sys_mfa(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS sys_terms_acceptance(
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL REFERENCES org_users(user_id) ON DELETE CASCADE,
    terms_version VARCHAR(20) NOT NULL,
    privacy_version VARCHAR(20) NOT NULL,
    accepted_at TIMESTAMP NOT NULL,
    UNIQUE (user_id, terms_version, privacy_version)
);

CREATE TABLE IF NOT EXISTS org_students(
    student_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL UNIQUE REFERENCES org_users(user_id),
    ra VARCHAR(30) UNIQUE,
    phone VARCHAR(20),
    last_activity DATE
);

CREATE TABLE IF NOT EXISTS org_loans(
    loan_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id INT NOT NULL REFERENCES org_students(student_id),
    operator_id INT NOT NULL REFERENCES org_users(user_id),
    loan_date TIMESTAMP NOT NULL,
    due_date DATE NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'OPEN'
);

CREATE TABLE IF NOT EXISTS org_loan_items(
    item_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id INT NOT NULL REFERENCES org_loans(loan_id),
    copy_id INT NOT NULL REFERENCES org_copies(copy_id),
    returned_at TIMESTAMP,
    returned_to INT REFERENCES org_users(user_id)
);

CREATE INDEX IF NOT EXISTS loans_student ON org_loans(student_id);
